<?php $dir = __DIR__."/database/migrations"; $files = glob("$dir/*.php"); $missingIndexes = 0; $noConstraints = 0; $totalFKs = 0; foreach($files as $f) { $content = file_get_contents($f); if(preg_match_all("/foreignId\((.*?)\)/", $content, $m)) { $totalFKs += count($m[0]); foreach($m[0] as $fk) { if(!str_contains($content, "constrained") && !str_contains($content, "references")) { $noConstraints++; } } } if(str_contains($content, "string(") && !str_contains($content, "index()")) { $missingIndexes++; } } echo "Total FKs: $totalFKs\nFKs without constraints: $noConstraints\nPotential missing indexes on strings: $missingIndexes\n";
